// when/days sent to GET /n8n/api/expiring. Change the days here if you like.
return [
  { json: { when: 'before', days: 3 } },
  { json: { when: 'today', days: 0 } },
  { json: { when: 'after', days: 2 } },
];

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const button = (url, label) => '<p style="margin:22px 0"><a href="' + esc(url) + '" style="display:inline-block;background:#e11d48;color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:12px;font-weight:700;font-size:16px">' + esc(label) + '</a></p>';
const layout = (title, bodyHtml, unsubscribeUrl) =>
  '<div style="font-family:system-ui,Segoe UI,Roboto,Arial,sans-serif;max-width:520px;margin:auto;color:#0f172a">' +
  '<h2 style="color:#e11d48;margin:0 0 6px">' + esc(title) + '</h2>' + bodyHtml +
  '<p style="color:#64748b;font-size:13px;margin-top:22px">Need help? Just reply to this email or message us on WhatsApp. 💚<br>— Team FluxFilm</p>' +
  (unsubscribeUrl ? '<p style="color:#94a3b8;font-size:11px;margin-top:18px">Don\'t want these emails? <a href="' + esc(unsubscribeUrl) + '" style="color:#94a3b8">Unsubscribe</a></p>' : '') +
  '</div>';

const x = $json;
const name = esc(x.greetingName || 'there');
const svc = esc(x.service); const plan = esc(x.plan);
let subject, title, body;
if (x.kind === 'EXPIRY_DAY') {
  subject = '⚠️ Your ' + x.service + ' plan ends today';
  title = 'Aaj last day hai! ⏰';
  body = '<p>Hi ' + name + ',</p><p>Your <b>' + svc + '</b> (' + plan + ') plan <b>ends today</b>. Renew now so your show doesn\'t stop in the middle. 🍿</p><p>It takes about a minute, and you keep the same account.</p>';
} else if (x.kind === 'AFTER') {
  const ago = x.daysLeft === -1 ? 'yesterday' : Math.abs(x.daysLeft) + ' days ago';
  subject = '😟 Your ' + x.service + ' plan ended ' + ago;
  title = 'We miss you! 💜';
  body = '<p>Hi ' + name + ',</p><p>Your <b>' + svc + '</b> (' + plan + ') plan ended <b>' + ago + '</b>.</p><p>Renew in the next few days to keep the <b>same account and profile</b>. Wapas aa jao! 🎬</p>';
} else {
  subject = '⏳ Your ' + x.service + ' plan ends in ' + x.daysLeft + ' days';
  title = 'Chhota sa reminder 👋';
  body = '<p>Hi ' + name + ',</p><p>Your <b>' + svc + '</b> (' + plan + ') plan ends on <b>' + esc(x.expiryText) + '</b> — ' + x.daysLeft + ' days left.</p><p>Renew early, tension-free raho. The new days are added <b>on top</b> of your plan, so you lose nothing.</p>';
}
return { json: Object.assign({}, x, { subject, html: layout(title, body + button(x.renewUrl, 'Renew now'), x.unsubscribeUrl) }) };
